def seed_default_channels() -> int:
    """Seeds the verified creators into channels table with categories and countries."""
    from radar.db import get_all_channels, get_db
    from radar.region import get_channel_region
    existing_ids = {c["channel_id"] for c in get_all_channels()}
    seeded_count = 0
    with get_db() as conn:
        for ch in SEED_CHANNELS:
            country = get_channel_region(handle=ch.get("handle", ""), name=ch.get("name", ""))
            if ch["channel_id"] not in existing_ids:
                url = f"https://www.youtube.com/{ch['handle']}"
                avatar_url = f"https://unavatar.io/youtube/{ch['handle']}"
                conn.execute("""
                    INSERT INTO channels (channel_id, name, handle, url, avatar_url, category, subscriber_count, median_views, country)
                    VALUES (?, ?, ?, ?, ?, ?, 50000, 15000, ?)
                """, (ch["channel_id"], ch["name"], ch["handle"], url, avatar_url, ch["category"], country))
                seeded_count += 1
            else:
                conn.execute("""
                    UPDATE channels
                    SET category = COALESCE(NULLIF(category, ''), ?),
                        handle = COALESCE(NULLIF(handle, ''), ?),
                        country = COALESCE(NULLIF(country, ''), ?)
                    WHERE channel_id = ?
                """, (ch["category"], ch["handle"], country, ch["channel_id"]))
    return seeded_count
